package com.smartpricing.shopify;

import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ShopifyRulesTest {
    @Test void domainsAreCanonicalAndCannotSelectArbitraryDestinations(){assertThat(ShopifyRules.shop(" Example-Shop.MYSHOPIFY.COM ")).isEqualTo("example-shop.myshopify.com");for(String shop:List.of("https://example.myshopify.com","example.myshopify.com.evil.test","127.0.0.1","example.myshopify.com:443","example.myshopify.com/path","user@example.myshopify.com","-example.myshopify.com","example-.myshopify.com","example.test.myshopify.com","example.myshopify.com?x=y"))assertThatThrownBy(()->ShopifyRules.shop(shop)).isInstanceOf(RuntimeException.class);}
    @Test void hmacMatchesRfc4231CaseOneAndCanonicalDecodedSorting(){assertThat(HexFormat.of().formatHex(ShopifyRules.hmac("Hi There","\u000b".repeat(20)))).isEqualTo("b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7");assertThat(ShopifyRules.canonical(Map.of("shop","example.myshopify.com","code","test-code","state","test-state","hmac","excluded"))).isEqualTo("code=test-code&shop=example.myshopify.com&state=test-state");}
    @Test void signaturesRejectForgeryDuplicatesStaleTimeAndInvalidState(){Instant now=Instant.parse("2026-11-12T00:00:00Z");Clock clock=Clock.fixed(now,ZoneOffset.UTC);String secret="ephemeral-test-only-secret";Map<String,String> values=new TreeMap<>(Map.of("code","test-code","shop","example.myshopify.com","state","a".repeat(64),"timestamp",Long.toString(now.getEpochSecond())));values.put("hmac",HexFormat.of().formatHex(ShopifyRules.hmac(ShopifyRules.canonical(values),secret)));Map<String,String[]> raw=new TreeMap<>();values.forEach((k,v)->raw.put(k,new String[]{v}));assertThat(ShopifyRules.verify(raw,secret,clock).get("shop")).isEqualTo("example.myshopify.com");assertThatThrownBy(()->ShopifyRules.verify(raw,"wrong-secret",clock)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->ShopifyRules.verify(raw,secret,Clock.fixed(now.plusSeconds(301),ZoneOffset.UTC))).isInstanceOf(RuntimeException.class);raw.put("shop",new String[]{"example.myshopify.com","evil.myshopify.com"});assertThatThrownBy(()->ShopifyRules.verify(raw,secret,clock)).isInstanceOf(RuntimeException.class);}
    @Test void encryptionUsesRandomAuthenticatedCiphertextAndBindsShopAndPurpose(){byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);String encoded=Base64.getEncoder().encodeToString(key);var settings=new ShopifySettings(false,"","",encoded,"");var cipher=new TokenCipher(settings);String token="ephemeral-test-token-not-a-real-credential",sealed=cipher.seal(token,"example.myshopify.com:access");assertThat(sealed).startsWith("v1:").doesNotContain(token).isNotEqualTo(cipher.seal(token,"example.myshopify.com:access"));assertThat(cipher.open(sealed,"example.myshopify.com:access")).isEqualTo(token);assertThatThrownBy(()->cipher.open(sealed,"other.myshopify.com:access")).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->cipher.open(sealed,"example.myshopify.com:refresh")).isInstanceOf(IllegalStateException.class);byte[] bytes=Base64.getDecoder().decode(sealed.substring(3));bytes[15]^=1;assertThatThrownBy(()->cipher.open("v1:"+Base64.getEncoder().encodeToString(bytes),"example.myshopify.com:access")).isInstanceOf(IllegalStateException.class);assertThat(settings.toString()).doesNotContain(encoded);}
    @Test void missingKeyAndUnsafeCallbackOriginFailClosed(){assertThatThrownBy(()->new TokenCipher(new ShopifySettings(false,"","","","")).validateKey()).isInstanceOf(IllegalStateException.class);for(String origin:List.of("http://example.test","https://user:pass@example.test","https://example.test/path","https://example.test?next=evil"))assertThatThrownBy(()->new ShopifySettings(true,"test","test","",origin).publicOrigin()).isInstanceOf(IllegalStateException.class);}
}
